mapper.sql:
SELECT day_of_week, MAX(effective_from) AS effective_from
FROM erp_bookstore_schedule
WHERE center_code = #{centerCode}
  AND effective_from <= #{baseDate}
GROUP BY day_of_week

mapper.select:
SELECT CASE WHEN EXISTS (
    SELECT 1 FROM erp_bookstore_schedule
    WHERE center_code = #{centerCode}
      AND day_of_week = #{dayOfWeek}
      AND effective_from = #{effectiveFrom}
) THEN 1 ELSE 0 END

SELECT COUNT(*)
FROM erp_bookstore_reservation r
JOIN erp_bookstore_slot_instance si ON si.slot_instance_id = r.slot_instance_id
WHERE si.center_code = #{centerCode}
  AND si.service_date >= #{fromDate}
  AND ((DATEDIFF(day, '19000101', si.service_date) % 7) + 1) = #{dayOfWeek}
  AND r.status = 'RESERVED'

mapper.insert:
INSERT INTO erp_bookstore_schedule_slot_del
    (log_type, logged_by, slot_template_id, center_code, day_of_week, effective_from,
     seq, start_time, end_time, capacity)
SELECT
    #{logType}, #{loggedBy}, slot_template_id, center_code, day_of_week, effective_from,
    seq, start_time, end_time, capacity
FROM erp_bookstore_schedule_slot
WHERE center_code = #{centerCode}
  AND day_of_week = #{dayOfWeek}
  AND effective_from = #{effectiveFrom}

mapper.delete:
DELETE FROM erp_bookstore_schedule
WHERE center_code = #{centerCode}
  AND day_of_week = #{dayOfWeek}
  AND effective_from = #{effectiveFrom}
